from pathlib import Path
import math
rows=[]
for line in Path('graphene.dat').read_text().splitlines():
 a,b=line.split('\t'); rows.append((1e7/float(a.replace(',','.')),float(b.replace(',','.'))))
rows.sort()
def solve(M,v):
 n=len(v); A=[M[i][:]+[v[i]] for i in range(n)]
 for i in range(n):
  k=max(range(i,n),key=lambda z:abs(A[z][i])); A[i],A[k]=A[k],A[i]
  if abs(A[i][i])<1e-20:return None
  q=A[i][i]; A[i]=[z/q for z in A[i]]
  for k in range(n):
   if k!=i:
    q=A[k][i]; A[k]=[A[k][j]-q*A[i][j] for j in range(n+1)]
 return [A[i][-1] for i in range(n)]
def fitlin(C,Y):
 p=len(C[0]);M=[[0.0]*p for _ in range(p)];v=[0.0]*p
 for c,y in zip(C,Y):
  for i in range(p):
   v[i]+=c[i]*y
   for j in range(p):M[i][j]+=c[i]*c[j]
 b=solve(M,v)
 if b is None:return 1e99,None
 return sum((y-sum(q*z for q,z in zip(b,c)))**2 for c,y in zip(C,Y)),b
def obj(data,x0,lg,deg):
 g=math.exp(lg); C=[];Y=[]
 scale=max(abs(x-x0) for x,y in data)
 for x,y in data:
  t=(x-x0)/scale; L=1/(1+((x-x0)/g)**2)
