 return fitlin(C,Y)
def nm(data,c,g,deg):
 def f(p):return obj(data,p[0],p[1],deg)[0]
 s=[[c,math.log(g)],[c+1,math.log(g)],[c,math.log(g)+.08]];v=list(map(f,s))
 for _ in range(800):
  z=sorted(range(3),key=lambda i:v[i]);s=[s[i] for i in z];v=[v[i] for i in z];a,b,w=s;fa,fb,fw=v
  m=[(a[0]+b[0])/2,(a[1]+b[1])/2];r=[2*m[0]-w[0],2*m[1]-w[1]];fr=f(r)
  if fr<fa:
   e=[3*m[0]-2*w[0],3*m[1]-2*w[1]];fe=f(e);s[2],v[2]=(e,fe) if fe<fr else (r,fr)
  elif fr<fb:s[2],v[2]=r,fr
  else:
   cc=[m[i]+.5*((r if fr<fw else w)[i]-m[i]) for i in range(2)];fc=f(cc)
   if fc<fw:s[2],v[2]=cc,fc
   else:
    s[1]=[(a[i]+s[1][i])/2 for i in range(2)];s[2]=[(a[i]+s[2][i])/2 for i in range(2)];v[1]=f(s[1]);v[2]=f(s[2])
